mapper.select:
SELECT e.id AS id, e.emp_no AS empNo, e.name, e.gender, e.dept_id AS deptId, e.job_id AS jobId, d.dept_name AS deptName, j.job_name AS jobName, e.phone, e.email, e.hire_date AS hireDate, e.account_status AS accountStatus FROM `emp` e LEFT JOIN `dept` d ON d.id = e.dept_id AND d.is_deleted = 0 LEFT JOIN `job` j ON j.id = e.job_id AND j.is_deleted = 0 WHERE e.is_deleted = 0
AND e.name LIKE CONCAT('%', #{query.name}, '%')
AND e.dept_id = #{query.deptId}
AND e.job_id = #{query.jobId}
AND e.hire_date >= #{query.hireDateStart}
AND e.hire_date <= #{query.hireDateEnd}
AND e.account_status = #{query.accountStatus}
ORDER BY e.created_at DESC
